const API_BASE =
  process.env.NEXT_PUBLIC_API_URL?.replace(/\/$/, "") ?? "http://localhost:4000";

export type ApiErrorBody = {
  error?: string;
  message?: string;
};

export async function apiFetch<T>(
  path: string,
  init: RequestInit = {},
): Promise<T> {
  const res = await fetch(`${API_BASE}${path}`, {
    ...init,
    headers: {
      "Content-Type": "application/json",
      ...(init.headers ?? {}),
    },
  });

  const data = (await res.json().catch(() => ({}))) as T & ApiErrorBody;
  if (!res.ok) {
    throw new Error(data.error ?? data.message ?? `Request failed (${res.status})`);
  }
  return data;
}

export type RegisterPayload = {
  email: string;
  password: string;
  address: string;
  phone: string;
};

export type UserProfile = {
  uid: string;
  email: string;
  address: string;
  phone: string;
  displayName?: string;
  photoURL?: string;
  provider?: string;
  createdAt: string;
  updatedAt: string;
};

export function registerUser(payload: RegisterPayload) {
  return apiFetch<{ user: UserProfile; message: string }>("/auth/register", {
    method: "POST",
    body: JSON.stringify(payload),
  });
}

export function fetchMe(idToken: string) {
  return apiFetch<{ user: UserProfile }>("/auth/me", {
    headers: { Authorization: `Bearer ${idToken}` },
  });
}

export function syncProfile(
  idToken: string,
  body: { displayName?: string; photoURL?: string; provider?: string } = {},
) {
  return apiFetch<{ user: UserProfile }>("/auth/sync", {
    method: "POST",
    headers: { Authorization: `Bearer ${idToken}` },
    body: JSON.stringify(body),
  });
}
